CREATE OR REPLACE FUNCTION sync_user_note() RETURNS trigger AS $$
BEGIN
  IF NEW.note IS DISTINCT FROM COALESCE(OLD.note, '') THEN
    NEW.customer_note := NEW.note;
  END IF;
  IF NEW.customer_note IS DISTINCT FROM COALESCE(OLD.customer_note, '') THEN
    NEW.note := NEW.customer_note;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER sync_user_note_trigger BEFORE INSERT OR UPDATE ON account_user FOR EACH ROW EXECUTE FUNCTION sync_user_note();
